import json
import csv

def get_cvss_score(vuln_data):
    """
    Extract CVSS v3 score from vulnerability data.
    Uses priority: NVD > GHSA > RedHat
    """
    cvss = vuln_data.get('CVSS', {})

    # Priority 1: NVD
    if 'nvd' in cvss:
        score = cvss['nvd'].get('V3Score')
        if score is not None:
            return score

    # Priority 2: GHSA
    if 'ghsa' in cvss:
        score = cvss['ghsa'].get('V3Score')
        if score is not None:
            return score

    # Priority 3: RedHat
    if 'redhat' in cvss:
        score = cvss['redhat'].get('V3Score')
        if score is not None:
            return score

    # Fallback to V2 if V3 is not available
    if 'nvd' in cvss:
        score = cvss['nvd'].get('V2Score')
        if score is not None:
            return score

    return 'N/A'

def generate_csv(json_input, csv_output):
    with open(json_input, 'r') as f:
        data = json.load(f)

    vulnerabilities = []

    if 'Results' in data:
        for result in data['Results']:
            if 'Vulnerabilities' in result:
                for vuln in result['Vulnerabilities']:
                    # Double check severity filter although we requested it in trivy command
                    severity = vuln.get('Severity', 'UNKNOWN')
                    if severity not in ['HIGH', 'CRITICAL']:
                        continue

                    vulnerabilities.append({
                        'Package': vuln.get('PkgName'),
                        'Version': vuln.get('InstalledVersion'),
                        'CVE_ID': vuln.get('VulnerabilityID'),
                        'Severity': severity,
                        'CVSS_Score': get_cvss_score(vuln),
                        'Fixed_Version': vuln.get('FixedVersion', 'N/A'),
                        'Title': vuln.get('Title', 'No description'),
                        'Url': vuln.get('PrimaryURL', '')
                    })

    headers = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url']

    with open(csv_output, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=headers)
        writer.writeheader()
        writer.writerows(vulnerabilities)

if __name__ == '__main__':
    generate_csv('/root/trivy_results.json', '/root/security_audit.csv')

